def find_shapes(g):
    g=[list(r) for r in g]; h=len(g); w=len(g[0]); seen=[[False]*w for _ in range(h)]; out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and not seen[i][j]:
                cells=[]; st=[(i,j)]; seen[i][j]=True
                while st:
                    r,c=st.pop(); cells.append((r,c))
                    for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
                        rr,cc=r+dr,c+dc
                        if 0<=rr<h and 0<=cc<w and g[rr][cc] and not seen[rr][cc]:
                            seen[rr][cc]=True; st.append((rr,cc))
                rs=[r for r,c in cells]; cs=[c for r,c in cells]
                top=min(rs); bot=max(rs); left=min(cs); right=max(cs)
                # stem cell = the cell not on the bar row
                barr=top if sum(1 for r in rs if r==top)>=3 else bot
                stem=[(r,c) for r,c in cells if r!=barr][0]
                up = stem[0] < barr  # stem above bar
                out.append({'stem':stem,'bar_r':barr,'bl':min(c for r,c in cells if r==barr),
                            'br_':max(c for r,c in cells if r==barr),'up':up})
    return out

def transform(g):
    shapes=find_shapes(g)
    ups=sorted([s for s in shapes if s['up']], key=lambda s:(s['stem'][0],s['stem'][1]))
    downs=sorted([s for s in shapes if not s['up']], key=lambda s:(s['stem'][0],s['stem'][1]))
    corners=[(0,0),(2,0),(0,2),(2,2)]
    out=[[0]*6 for _ in range(3)]
    for k,s in enumerate(ups):
        pr,pc=corners[k]; out[pr][pc]=3
    for k,s in enumerate(downs):
        pr,pc=corners[k]; out[pr][pc+3]=1
    return out

